// Lọc webhook Trello: chỉ giữ các event mà ít nhất một rule quan tâm.
// Khi thêm rule mới cần event khác (vd: chuyển list), bổ sung vào đây.
// Lưu ý chống loop: không nhận updateCard chỉ đổi due/label/... do chính flow ghi ra.
const CREATE_EVENTS = [
  'createCard',
  'copyCard',
  'convertToCardFromCheckItem',
  'emailCard',
  'moveCardToBoard',
];

const out = [];
for (const item of $input.all()) {
  const action = item.json.action;
  const card = action?.data?.card;
  if (!card?.id) continue;

  const old = action.data.old ?? {};
  const nameChanged = action.type === 'updateCard' && typeof old.name === 'string';
  if (!CREATE_EVENTS.includes(action.type) && !nameChanged) continue;

  out.push({
    json: {
      event: action.type,
      actionId: action.id,
      cardId: card.id,
      oldName: nameChanged ? old.name : null,
      by: action.memberCreator?.username ?? null,
    },
  });
}
return out;

// ===== Cấu hình =====
const TZ = 'Asia/Tokyo';
const DEFAULT_TIME = { hour: 9, minute: 0 }; // khi tiêu đề chỉ có ngày
const CLEAR_DUE_WHEN_TAG_REMOVED = false; // xoá "@ngày" khỏi tiêu đề thì xoá luôn due

// ===== Parser "@yyyy/m/d hh:mm" =====
// Hỗ trợ: @2026/8/9 13:30 · @ 2026/08/09 @ 13:30 · @2026-8-9 · @8/9 9:00 · @2026年8月9日 13時30分
// Ký tự full-width (＠２０２６／８／９) được chuẩn hoá bằng NFKC.
const DATE_TAG =
  /@\s*(?:(\d{4})\s*[\/\-.年]\s*)?(\d{1,2})\s*[\/\-.月]\s*(\d{1,2})(?!\d)日?(?:\s*@?\s*(\d{1,2})\s*[:時]\s*(\d{2})(?!\d)分?)?/g;

function parseDue(title, now) {
  if (!title) return null;
  const text = title.normalize('NFKC');
  let result = null;
  for (const m of text.matchAll(DATE_TAG)) {
    const [, y, mo, d, h, mi] = m;
    const hasTime = h !== undefined;
    const parts = {
      month: +mo,
      day: +d,
      hour: hasTime ? +h : DEFAULT_TIME.hour,
      minute: hasTime ? +mi : DEFAULT_TIME.minute,
    };
    let dt = DateTime.fromObject({ year: y ? +y : now.year, ...parts }, { zone: TZ });
    // Không ghi năm và ngày đã qua -> hiểu là năm sau
    if (!y && dt.isValid && dt < now.startOf('day')) dt = dt.plus({ years: 1 });
    // Luxon không báo lỗi với 24:00 nên tự kiểm tra
    if (dt.isValid && parts.hour < 24 && parts.minute < 60) result = dt; // lấy tag hợp lệ cuối cùng
  }
  return result;
}

// ===== Rules =====
// Mỗi rule nhận { card, event, now } và trả về mảng action Trello API:
// { method, path, body, rule }. Thêm rule mới = viết hàm mới rồi thêm vào RULES.

function dueFromTitle({ card, event, now }) {
  const due = parseDue(card.name, now);
  if (due) {
    const current = card.due ? DateTime.fromISO(card.due).toMillis() : null;
    if (current === due.toMillis()) return [];
    return [
      {
        rule: 'due-from-title',
        method: 'PUT',
        path: `cards/${card.id}`,
        body: { due: due.toUTC().toISO() },
      },
    ];
  }
  if (CLEAR_DUE_WHEN_TAG_REMOVED && card.due && parseDue(event.oldName, now)) {
    return [{ rule: 'due-from-title', method: 'PUT', path: `cards/${card.id}`, body: { due: null } }];
  }
  return [];
}

const RULES = [dueFromTitle];

// ===== Engine =====
const now = DateTime.now().setZone(TZ);
const out = [];
$input.all().forEach((item, i) => {
  const card = item.json;
  const event = $('Normalize event').itemMatching(i).json;
  for (const rule of RULES) {
    for (const action of rule({ card, event, now })) {
      out.push({ json: { ...action, cardId: card.id, cardName: card.name } });
    }
  }
});
return out;
